// Slide 7: interactive fretboard. It contains no music theory of its own:
// every note, interval and position comes from src/data/fretboard.json,
// generated by `python -m guitarlab.build`. Fret spacing uses the
// generated equal-temperament fret positions, so the diagram is to scale.
// Orientation follows tablature convention (always LTR): nut on the left,
// high E string on top.

const SVG_NS = 'http://www.w3.org/2000/svg';
const SHOWN_FRETS = 15;
const X_NUT = 62, X_END = 985;
const Y_TOP = 26, STRING_GAP = 36;
const INLAYS = [3, 5, 7, 9, 15];

const SCALE_LABELS = {
  minor_pentatonic: 'פנטטוני מינורי',
  major_pentatonic: 'פנטטוני מז׳ורי',
  natural_minor: 'מינור טבעי (אאולי)',
  major: 'מז׳ור (יוני)',
};
const SCALE_ORDER = ['minor_pentatonic', 'major_pentatonic', 'natural_minor', 'major'];

// Wrap LTR fragments (fret ranges, note lists) in Unicode isolates so they keep
// their order inside Hebrew text, including <option> labels where <bdi> can't be used.
const ltr = (s) => `⁦${s}⁩`;

const el = (name, attrs = {}) => {
  const node = document.createElementNS(SVG_NS, name);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  return node;
};

export function initFretboardError(message) {
  const root = document.getElementById('fretboard');
  root.replaceChildren();
  const box = document.createElement('div');
  box.className = 'fretboard__error';
  box.innerHTML = '<strong>נתוני הצוואר לא נטענו.</strong> <span></span><p class="note">הקובץ <code dir="ltr">src/data/fretboard.json</code> נוצר על ידי <code dir="ltr">cd python &amp;&amp; python -m guitarlab.build</code>.</p>';
  box.querySelector('span').textContent = message;
  root.append(box);
}

export function initFretboard(data) {
  const svg = document.getElementById('fb-svg');
  const scaleSel = document.getElementById('fb-scale');
  const keySel = document.getElementById('fb-key');
  const posSel = document.getElementById('fb-position');
  const posField = document.getElementById('fb-position-field');
  const legendOut = document.getElementById('fb-legend-out');
  const summary = document.getElementById('fb-summary');
  const labelButtons = [...document.querySelectorAll('[data-labels]')];

  const state = { scale: 'minor_pentatonic', key: 'A', position: '1', labels: 'names' };

  // Geometry from the generated fret positions (distance from the nut).
  const dist = data.fret_positions.distance_from_nut_in;
  const fretX = (n) => X_NUT + (dist[n] / dist[SHOWN_FRETS]) * (X_END - X_NUT);
  const noteX = (f) => (f === 0 ? X_NUT - 24 : (fretX(f - 1) + fretX(f)) / 2);
  const strings = data.tuning.strings; // low E first
  const stringY = (si) => Y_TOP + (strings.length - 1 - si) * STRING_GAP;
  const yMid = (stringY(2) + stringY(3)) / 2;

  drawBoard();
  const notesLayer = svg.appendChild(el('g'));

  for (const id of SCALE_ORDER.filter((id) => id in data.scales)) {
    scaleSel.append(new Option(SCALE_LABELS[id] ?? data.scales[id].name_en, id));
  }
  scaleSel.value = state.scale;

  scaleSel.addEventListener('change', () => {
    const prevPc = currentKey().notes[0].pc;
    state.scale = scaleSel.value;
    // keep the same tonic pitch even if its spelling differs (e.g. C# / Db)
    const keys = data.scales[state.scale].keys;
    state.key = Object.keys(keys).find((k) => keys[k].notes[0].pc === prevPc);
    fillKeys();
    fillPositions();
    render();
  });
  keySel.addEventListener('change', () => { state.key = keySel.value; fillPositions(); render(); });
  posSel.addEventListener('change', () => { state.position = posSel.value; render(); });
  for (const b of labelButtons) {
    b.addEventListener('click', () => {
      state.labels = b.dataset.labels;
      labelButtons.forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
      render();
    });
  }

  fillKeys();
  fillPositions();
  render();
  showProvenance(data);

  function currentKey() { return data.scales[state.scale].keys[state.key]; }

  // On small screens the diagram scrolls horizontally: bring the selected
  // position into view instead of leaving it off-screen.
  function revealPosition(key, pos) {
    const figure = svg.closest('.fretboard__figure');
    if (figure.scrollWidth <= figure.clientWidth + 1) return;
    const scale = svg.getBoundingClientRect().width / 1000;
    const startFret = pos === null ? 0 : key.positions[pos - 1].span[0];
    const left = startFret <= 1 ? 0 : fretX(startFret - 1) * scale - 24;
    figure.scrollTo({ left: Math.max(0, left), behavior: 'smooth' });
  }

  function fillKeys() {
    keySel.replaceChildren(...Object.keys(data.scales[state.scale].keys).map((k) => new Option(k, k)));
    keySel.value = state.key;
  }

  function fillPositions() {
    const { positions } = currentKey();
    posField.hidden = positions.length === 0;
    legendOut.hidden = positions.length === 0;
    posSel.replaceChildren(
      new Option('כל הצוואר', 'all'),
      ...positions.map((p) => new Option(`תנוחה ${p.number} · סריגים ${ltr(`${p.span[0]}–${p.span[1]}`)}`, String(p.number))),
    );
    if (!positions.length) state.position = 'all';
    else if (state.position !== 'all' && !positions.some((p) => String(p.number) === state.position)) state.position = '1';
    posSel.value = state.position;
  }

  function drawBoard() {
    const yTop = stringY(strings.length - 1) - 14, yBot = stringY(0) + 14;
    svg.append(el('rect', { class: 'fb-board', x: X_NUT, y: yTop, width: X_END - X_NUT, height: yBot - yTop, rx: 4 }));
    for (const n of INLAYS) svg.append(el('circle', { class: 'fb-inlay', cx: noteX(n), cy: yMid, r: 6 }));
    svg.append(el('circle', { class: 'fb-inlay', cx: noteX(12), cy: (stringY(4) + stringY(3)) / 2, r: 6 }));
    svg.append(el('circle', { class: 'fb-inlay', cx: noteX(12), cy: (stringY(2) + stringY(1)) / 2, r: 6 }));
    for (let n = 1; n <= SHOWN_FRETS; n++) svg.append(el('line', { class: 'fb-fret', x1: fretX(n), x2: fretX(n), y1: yTop, y2: yBot }));
    svg.append(el('line', { class: 'fb-nut', x1: X_NUT, x2: X_NUT, y1: yTop - 1, y2: yBot + 1 }));
    strings.forEach((s, si) => {
      // thicker strings for lower pitches, as on a real neck
      svg.append(el('line', { class: 'fb-string', x1: X_NUT - 40, x2: X_END, y1: stringY(si), y2: stringY(si), 'stroke-width': 2.6 - si * 0.32 }));
      const name = el('text', { class: 'fb-stringname', x: 14, y: stringY(si) });
      name.textContent = s.name;
      svg.append(name);
    });
    for (const n of [3, 5, 7, 9, 12, 15]) {
      const t = el('text', { class: 'fb-fretnum', x: noteX(n), y: yBot + 20 });
      t.textContent = n;
      svg.append(t);
    }
  }

  function render() {
    const key = currentKey();
    const pos = state.position === 'all' ? null : Number(state.position);
    notesLayer.replaceChildren();
    let shown = 0;
    for (const [si, fret, name, interval, positions] of key.cells) {
      if (fret > SHOWN_FRETS) continue;
      const inPos = pos === null || positions.includes(pos);
      if (inPos) shown++;
      const g = el('g', { class: `fb-note${interval === '1' ? ' is-root' : ''}${inPos ? '' : ' is-out'}` });
      const x = noteX(fret), y = stringY(si);
      g.append(el('circle', { cx: x, cy: y, r: 13 }));
      const label = el('text', { x, y });
      label.textContent = state.labels === 'names' ? name : interval;
      const title = el('title');
      title.textContent = `${name} (${interval}) · מיתר ${strings[si].number} · סריג ${fret}`;
      g.append(label, title);
      notesLayer.append(g);
    }
    const scaleName = SCALE_LABELS[state.scale];
    const where = pos === null ? `כל הצוואר (סריגים ${ltr('0–15')})` : `תנוחה ${pos}, סריגים ${ltr(key.positions[pos - 1].span.join('–'))}`;
    revealPosition(key, pos);
    summary.textContent = `${ltr(state.key)} ${scaleName} · ${where} · ${shown} תווים · תווי הסולם: ${ltr(key.notes.map((n) => n.name).join(' '))}`;
  }
}

function showProvenance(data) {
  const box = document.getElementById('fb-provenance');
  const combos = Object.values(data.scales).reduce((n, s) => n + Object.keys(s.keys).length, 0);
  const { generator, generator_version: version, content_sha256: hash, source } = data.meta;
  box.innerHTML = `
    <strong>הנתונים בשקף זה נוצרו ב-Python</strong>
    <span><code dir="ltr"></code></span>
    <span><code dir="ltr"></code></span>
    <span></span>`;
  const [genLine, hashLine] = box.querySelectorAll('code');
  genLine.textContent = `${generator} ${version} · ${source}`;
  hashLine.textContent = `sha256 ${hash.slice(0, 16)}…`;
  box.lastElementChild.textContent = `${combos} צירופי סולם וטוניקה · כוונון סטנדרטי · ${data.frets} סריגים`;
  box.title = `sha256 ${hash}`;
}
